public partial class GameForm {
 readonly GameAudio audio=new GameAudio();bool exhibition;int quickHome,quickAway=1,quickChoosing;string coachDraft="";int awardCategory,historyTeam;
 readonly List<MenuTarget> menuTargets=new List<MenuTarget>();class MenuTarget{public RectangleF Bounds;public int Index;}
 static readonly string[] AwardTypes={"CHAMPIONSHIP","MVP","OPOTY"};
 bool IsBeta(){return screen=="audio"||screen=="home"||screen=="franchisehub"||screen=="exhibition"||screen=="quickteam"||screen=="settings"||screen=="coach"||screen=="coachname"||screen=="trophies"||screen=="awards"||screen=="history"||screen=="historyteam"||screen=="champions"||screen=="leaders";}
 void HitArea(float x,float y,float width,float height,int index){MenuTarget hit=new MenuTarget();hit.Bounds=new RectangleF(x,y,width,height);hit.Index=index;menuTargets.Add(hit);}
 void MouseMenu(Point location){PointF p=new PointF(location.X*1280f/ClientSize.Width,location.Y*800f/ClientSize.Height);if(screen=="designer"){DesignerMouse(p);return;}if(screen=="audio"){AudioMouse(p);return;}foreach(MenuTarget target in menuTargets)if(target.Bounds.Contains(p)){if(screen=="leaders"&&target.Index>=300&&target.Index<305){ChangeRace(target.Index-300);return;}if(screen=="game"&&OnsideMouseAction(target.Index)){Invalidate();return;}if(screen=="game"&&target.Index==100){audio.Muted=!audio.Muted;Invalidate();return;}selection=target.Index;audio.Play("confirm");ActivateSelection();Invalidate();break;}}
 int BetaCount(){if(screen=="audio")return 8;if(screen=="home")return 4;if(screen=="franchisehub")return 7;if(screen=="exhibition")return 5;if(screen=="quickteam")return 13;if(screen=="settings")return 5;if(screen=="coach")return 6;if(screen=="coachname")return 40;if(screen=="trophies")return 4;return BetaRows().Count;}
 List<string> BetaRows(){if(screen=="leaders")return RaceRows();List<string> rows=new List<string>();if(screen=="awards"||screen=="champions"){string type=screen=="champions"?"CHAMPIONSHIP":AwardTypes[awardCategory];for(int i=franchise.Awards.Count-1;i>=0;i--){SeasonAward a=franchise.Awards[i];if(a.Type==type)rows.Add("S"+a.Season+"  "+a.Winner+" / "+a.Club);}}else if(screen=="history"){for(int i=franchise.History.Count-1;i>=0;i--){TeamSeason h=franchise.History[i];rows.Add("S"+h.Season+" "+h.Name+" "+h.W+"-"+h.L+"-"+h.T+(h.Champion?" CHAMP":""));}}else if(screen=="historyteam"){foreach(TeamSeason h in franchise.History)if(h.Team==historyTeam)rows.Add("S"+h.Season+"  "+h.W+"-"+h.L+"-"+h.T+"  "+h.PF+" PF"+(h.Champion?" CHAMP":""));}else if(screen=="leaders"){List<SeasonProduction> leaders=new List<SeasonProduction>(franchise.Production);leaders.Sort((a,b)=>b.OffenseScore.CompareTo(a.OffenseScore));foreach(SeasonProduction p in leaders)rows.Add(p.Name+" "+p.Role+" / "+franchise.Teams[p.Team].Mascot+" / "+(int)p.OffenseScore+" PTS");}if(rows.Count==0)rows.Add(screen=="leaders"?"PLAY A GAME TO START":"YOUR STORY STARTS THIS SEASON");rows.Add("BACK");return rows;}
 void ActivateBeta(){if(screen=="audio"){ActivateAudio();return;}if(screen=="home"){if(selection==0){quickHome=franchise.UserTeam;quickAway=(quickHome+1)%12;Open("exhibition");}else if(selection==1)Open("franchisehub");else if(selection==2)Open("settings");else Close();}
  else if(screen=="franchisehub"){if(selection==0){if(franchise.Fired)Open("league");else StartGame();}else if(selection==1)Open("club");else if(selection==2)Open("coach");else if(selection==3)Open("trophies");else if(selection==4)Open("history");else if(selection==5)Open("champions");else Open("home");}
  else if(screen=="exhibition"){if(selection<2){quickChoosing=selection;Open("quickteam");}else if(selection==2)StartExhibition(false);else if(selection==3)StartExhibition(true);else Open("home");}
  else if(screen=="quickteam"){if(selection<12){if(quickChoosing==0){quickHome=selection;if(quickAway==quickHome)quickAway=(quickHome+1)%12;}else{quickAway=selection;if(quickHome==quickAway)quickHome=(quickAway+1)%12;}}Open("exhibition");}
  else if(screen=="settings"){if(selection==0)audio.Muted=!audio.Muted;else if(selection==1)ToggleFull();else if(selection==2){returnScreen="settings";Open("help");}else if(selection==3)ChangeDifficulty();else Open("home");}
  else if(screen=="coach"){if(selection==0){coachDraft=franchise.Coach.Name;Open("coachname");selection=38;}else if(selection==1)franchise.Coach.Skin=(franchise.Coach.Skin+1)%4;else if(selection==2)franchise.Coach.Hair=(franchise.Coach.Hair+1)%4;else if(selection==3)franchise.Coach.Hat=(franchise.Coach.Hat+1)%3;else if(selection==4)franchise.Coach.Outfit=(franchise.Coach.Outfit+1)%9;else Open("franchisehub");franchise.Save();}
  else if(screen=="coachname"){string letters="ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";if(selection<36&&coachDraft.Length<16)coachDraft+=letters[selection];else if(selection==36&&coachDraft.Length<16)coachDraft+=" ";else if(selection==37&&coachDraft.Length>0)coachDraft=coachDraft.Substring(0,coachDraft.Length-1);else if(selection==38){franchise.NameCoach(coachDraft);Open("coach");}else if(selection==39)Open("coach");}
  else if(screen=="trophies"){if(selection<3){awardCategory=selection;Open("awards");}else Open("franchisehub");}
  else if(selection==BetaRows().Count-1)Open(screen=="awards"?"trophies":screen=="historyteam"?"history":"franchisehub");
  else if(screen=="history"&&franchise.History.Count>0){historyTeam=franchise.History[franchise.History.Count-1-selection].Team;Open("historyteam");}
 }
 bool CoachTyping(Keys key){if(screen!="coachname")return false;if(key>=Keys.A&&key<=Keys.Z||key>=Keys.D0&&key<=Keys.D9||key==Keys.Space){if(coachDraft.Length<16)coachDraft+=key==Keys.Space?' ':(char)(int)key;selection=38;Invalidate();return true;}if(key==Keys.Back){if(coachDraft.Length>0)coachDraft=coachDraft.Substring(0,coachDraft.Length-1);Invalidate();return true;}return false;}
 void StartExhibition(bool practice){Franchise sandbox=Franchise.Create(new Profile(),new Roster());sandbox.UserTeam=quickHome;foreach(LeagueTeam t in sandbox.Teams)t.CoachOff=t.CoachDef=t.CoachFit=0;game=new Simulation();game.Practice=practice;game.Exhibition=true;game.Difficulty=difficulty;sandbox.Apply(game,quickAway);game.Postseason=game.Championship=false;game.BowlName="";game.NewGame();exhibition=true;matchFixture=-1;awarded=false;screen="game";cameraZ=13;cameraX=0;pendingThrow=0;stickReady=true;}
 void Tile(string label,int icon,float x,float y,float w,float h,int index){Rect(x,y,w,h,selection==index?Color.FromArgb(67,93,100):Color.FromArgb(38,45,62));if(selection==index){Rect(x,y,w,4,Gold);Rect(x,y,4,h,Gold);}MenuPicture(label,x+w/2-25,y+12,50);TextAt(label,x+w/2-PixelFont.Width(label,12)/2,y+h-25,12,White);HitArea(x,y,w,h,index);}
 void DrawIcon(int kind,float x,float y,float size,Color color){float u=size/10;if(kind>=8){ExtraIcon(kind,x,y,u,color);return;}Action<float,float,float,float> r=(a,b,w,h)=>Rect(x+a*u,y+b*u,w*u,h*u,color);int icon=kind%8;if(icon==0){r(2,0,6,2);r(0,2,10,2);r(2,4,6,6);r(4,4,2,4);}else if(icon==1){r(1,1,3,3);r(6,6,3,3);r(1,5,7,1);r(6,1,1,7);r(7,2,2,1);r(1,7,2,1);}else if(icon==2){r(4,0,2,10);r(0,4,10,2);}else if(icon==3){r(1,0,8,2);r(3,2,4,4);r(4,6,2,2);r(1,8,8,2);r(0,2,2,3);r(8,2,2,3);}else if(icon==4){r(1,3,8,6);r(3,1,4,2);Rect(x+4*u,y+5*u,2*u,4*u,Ink);}else if(icon==5){r(0,0,10,10);Rect(x+u,y+u,8*u,8*u,Ink);r(2,2,1,6);r(4,4,1,4);r(6,1,1,7);r(8,5,1,3);}else if(icon==6){r(0,1,10,1);r(0,5,10,1);r(0,9,10,1);r(1,0,1,10);r(5,0,1,10);r(9,0,1,10);}else{r(1,0,8,2);r(0,2,10,5);r(2,7,6,2);Rect(x+3*u,y+2*u,4*u,3*u,Ink);}}
 void CoachPortrait(float x,float y,float scale){CoachRecord c=franchise.Coach;Color[] skins={Color.FromArgb(99,58,42),Color.FromArgb(171,110,75),Color.FromArgb(221,161,114),Color.FromArgb(245,203,162)};Color shirt=Color.FromArgb(255,Color.FromArgb(Franchise.Palette[c.Outfit]));Action<int,int,int,int,Color> r=(a,b,w,h,color)=>Rect(x+a*scale,y+b*scale,w*scale,h*scale,color);r(3,13,4,9,Color.FromArgb(43,51,70));r(9,13,4,9,Color.FromArgb(43,51,70));r(2,8,12,8,shirt);r(0,9,2,7,skins[c.Skin]);r(14,9,2,7,skins[c.Skin]);r(4,0,8,8,skins[c.Skin]);r(4,0,8,1+c.Hair%3,Color.FromArgb(65+c.Hair*20,42+c.Hair*12,30));r(6,4,1,1,Ink);r(10,4,1,1,Ink);r(7,6,3,1,Ink);if(c.Hat>0){r(3,0,10,2,TeamPrimary);r(c.Hat==1?2:10,2,5,1,TeamSecondary);}r(2,21,5,2,White);r(9,21,5,2,White);}
