  if(screen=="quickteam"){TextAt("CHOOSE TEAM",48,38,30,White);for(int i=0;i<12;i++)Tile(franchise.Teams[i].Mascot,0,44+(i%4)*302,115+(i/4)*180,282,160,i);Tile("BACK",1,44,674,1188,70,12);return;}
